namespace Puppis.Architecture.Tests;

public static class CommentRules
{
    private static readonly string[] DirectivesAToolReads =
    [
        "<auto-generated",
        "<autogenerated",
        "csharpier-ignore",
    ];

    public static IReadOnlyList<string> PlacesThatCarryAComment(string root)
        =>
        [
            .. new[] { "src", "tests" }
                .SelectMany(folder => SourceScan.Files(Path.Combine(root, folder)))
                .SelectMany(file => Comments(root, file)),
        ];

    public static IReadOnlyList<SourceComment> CommentsIn(string source)
        => [.. CommentScanner.Find(source).Where(comment => !IsADirectiveAToolReads(comment))];

    private static IEnumerable<string> Comments(string root, string file)
        => CommentsIn(File.ReadAllText(file))
            .Select(comment => $"{Path.GetRelativePath(root, file).Replace('\\', '/')}:{comment.Line}");

    private static bool IsADirectiveAToolReads(SourceComment comment)
        => comment.Text.StartsWith("//", StringComparison.Ordinal)
           && DirectivesAToolReads.Any(directive =>
               comment.Text.TrimStart('/').TrimStart().StartsWith(directive, StringComparison.Ordinal));
}
